var ERR_NAMES = {1:'FRAME',2:'CHECKSUM',3:'NOT_READY',4:'LIMIT',5:'OPCODE',6:'ARGUMENT',7:'COLLISION'};

function hi16(v) { return (v >> 8) & 0xff; }
function lo16(v) { return v & 0xff; }

function toHexByte(b) {
  var s = (b & 0xff).toString(16);
  return s.length < 2 ? '0' + s : s;
}

function buildFrame(payload) {
  var len = payload.length;
  if (len > 255) throw new Error('payload too long');
  var bytes = [0xa5, len].concat(payload);
  var c = 0;
  for (var i = 1; i < bytes.length; i++) c ^= bytes[i];
  bytes.push(c & 0xff);
  var out = '';
  for (var j = 0; j < bytes.length; j++) out += toHexByte(bytes[j]);
  return out;
}

function encode(command) {
  var payload;
  if (Array.isArray(command)) {
    if (command.length !== 2) throw new Error('ARGUMENT: need 2 channels');
    var a = Math.round(Number(command[0]) * 10000);
    var b = Math.round(Number(command[1]) * 10000);
    if (!isFinite(a) || !isFinite(b)) throw new Error('ARGUMENT: not finite');
    if (Math.abs(a) > 1000 || Math.abs(b) > 1000) throw new Error('ARGUMENT: out of range');
    payload = [0x10, hi16(a), lo16(a), hi16(b), lo16(b)];
  } else if (command && typeof command === 'object' && command.op === 'lift') {
    if (command.position === 'up') payload = [0x20, 1];
    else if (command.position === 'down') payload = [0x20, 0];
    else throw new Error('ARGUMENT: lift position');
  } else if (command && typeof command === 'object' && command.op === 'grip') {
    if (command.state === 'closed') payload = [0x21, 1];
    else if (command.state === 'open') payload = [0x21, 0];
    else throw new Error('ARGUMENT: grip state');
  } else {
    throw new Error('ARGUMENT: unknown command');
  }
  return buildFrame(payload);
}

function s16(hi, lo) {
  var v = ((hi & 0xff) << 8) | (lo & 0xff);
  if (v & 0x8000) v -= 0x10000;
  return v;
}

function decode(rawReply) {
  if (typeof rawReply !== 'string') throw new Error('FRAME: not a string');
  var hex = rawReply.trim().toLowerCase();
  if (hex.length < 8 || hex.length % 2 !== 0 || !/^[0-9a-f]+$/.test(hex)) throw new Error('FRAME: bad hex');
  var bytes = [];
  for (var i = 0; i < hex.length; i += 2) bytes.push(parseInt(hex.substr(i, 2), 16));
  if (bytes[0] !== 0xa5) throw new Error('FRAME: bad sync');
  var len = bytes[1];
  if (bytes.length !== len + 3) throw new Error('FRAME: length mismatch');
  var c = 0;
  for (var k = 1; k < len + 2; k++) c ^= bytes[k];
  if ((c & 0xff) !== bytes[len + 2]) throw new Error('CHECKSUM: mismatch');
  var payload = bytes.slice(2, 2 + len);
  if (payload.length < 2) throw new Error('FRAME: payload too short');
  var status = payload[0];
  if (status !== 0) {
    throw new Error((ERR_NAMES[status] || 'UNKNOWN') + ': device status ' + status);
  }
  var opcode = payload[1];
  if (opcode === 0x10) {
    if (len < 7) throw new Error('FRAME: step reply too short');
    var a = s16(payload[2], payload[3]) / 10000;
    var b = s16(payload[4], payload[5]) / 10000;
    return { applied: [a, b], limited: (payload[6] & 1) === 1 };
  }
  if (opcode === 0x20) {
    if (len < 4) throw new Error('FRAME: lift reply too short');
    if (payload[2] !== 0 && payload[2] !== 1) throw new Error('ARGUMENT: bad lift position');
    return { applied: { op: 'lift', position: payload[2] === 1 ? 'up' : 'down' }, limited: (payload[3] & 1) === 1 };
  }
  if (opcode === 0x21) {
    if (len < 4) throw new Error('FRAME: grip reply too short');
    if (payload[2] !== 0 && payload[2] !== 1) throw new Error('ARGUMENT: bad grip state');
    return { applied: { op: 'grip', state: payload[2] === 1 ? 'closed' : 'open' }, limited: (payload[3] & 1) === 1 };
  }
  throw new Error('OPCODE: unexpected reply opcode ' + opcode);
}

