function clampU(v) {
  if (!isFinite(v)) return 0;
  if (v > 0.1) v = 0.1;
  if (v < -0.1) v = -0.1;
  return Math.round(v * 10000) / 10000;
}

function probeCmd(cc00, cc11) {
  return cc00 <= cc11 ? [0.05, 0] : [0, 0.05];
}

function control(state) {
  var tol = state.tolerancePx || 7;
  var tip = state.tip, tgt = state.target;
  var ex = tgt[0] - tip[0], ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: 'stop', reason: 'non-finite error' };
  if (err <= tol) return { action: 'verify' };

  var h = state.history || [];
  var n = h.length;
  var start = Math.max(0, n - 40);
  var cc00 = 0, cc01 = 0, cc11 = 0;
  var m00 = 0, m01 = 0, m10 = 0, m11 = 0;
  for (var i = start; i < n; i++) {
    var c = h[i].command, d = h[i].delta;
    if (!c || !d) continue;
    var c0 = c[0], c1 = c[1], dx = d[0], dy = d[1];
    if (!isFinite(c0) || !isFinite(c1) || !isFinite(dx) || !isFinite(dy)) continue;
    cc00 += c0 * c0; cc01 += c0 * c1; cc11 += c1 * c1;
    m00 += dx * c0; m01 += dx * c1;
    m10 += dy * c0; m11 += dy * c1;
  }

  var detC = cc00 * cc11 - cc01 * cc01;
  if (n === 0 || !(detC > 1e-6 * Math.max(cc00, cc11, 1e-12) * Math.max(cc00, cc11, 1e-12) && detC > 1e-8)) {
    var p = probeCmd(cc00, cc11);
    return { action: 'move', u: p };
  }

  // J = M * inv(CC)
  var i00 = cc11 / detC, i01 = -cc01 / detC, i10 = -cc01 / detC, i11 = cc00 / detC;
  var j00 = m00 * i00 + m01 * i10;
  var j01 = m00 * i01 + m01 * i11;
  var j10 = m10 * i00 + m11 * i10;
  var j11 = m10 * i01 + m11 * i11;
  var detJ = j00 * j11 - j01 * j10;
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-9) {
    return { action: 'move', u: probeCmd(cc00, cc11) };
  }

  // u = inv(J) * err, damped
  var k00 = j11 / detJ, k01 = -j01 / detJ, k10 = -j10 / detJ, k11 = j00 / detJ;
  var gain = 0.5;
  var u0 = gain * (k00 * ex + k01 * ey);
  var u1 = gain * (k10 * ex + k11 * ey);
  u0 = clampU(u0);
  u1 = clampU(u1);
  if (u0 === 0 && u1 === 0) {
    return { action: 'move', u: probeCmd(cc00, cc11) };
  }
  return { action: 'move', u: [u0, u1] };
}
